import { AgeGroup, Class, Dance, Discipline, PaymentStatus, Role, RoundStatus, RoundType } from '@bis/shared'
import { index, integer, primaryKey, real, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core'

// Drizzle wants a non-empty tuple of the allowed strings
const oneOf = <T extends Record<string, string>>(values: T) =>
  Object.values(values) as [T[keyof T], ...Array<T[keyof T]>]

// Ids are generated by the app, not the database, so venue and cloud rows never collide when they sync.
// Timestamps are ISO 8601 UTC strings; the venue laptop's clock is the source of truth on the day.
const id = () => text('id').primaryKey()

export const competitions = sqliteTable('competitions', {
  id: id(),
  name: text('name').notNull(),
  date: text('date').notNull(),
  venue: text('venue').notNull(),
  organizer: text('organizer').notNull(),
  // The round on the floor now; the scrutineer sets it
  floorRoundId: text('floor_round_id'),
  // Cloud only: the venue that downloaded this competition and now runs it. While held, entries and payments for it
  // cannot change online, so there is only ever one place making changes.
  heldBy: text('held_by'),
  heldAt: text('held_at'),
})

export const clubs = sqliteTable('clubs', {
  id: id(),
  name: text('name').notNull(),
  contactName: text('contact_name').notNull(),
  contactEmail: text('contact_email').notNull(),
  contactPhone: text('contact_phone').notNull(),
  // Null for clubs added by staff who have no portal account yet
  passwordHash: text('password_hash'),
}, (t) => [uniqueIndex('clubs_email').on(t.contactEmail)])

export const events = sqliteTable(
  'events',
  {
    id: id(),
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    // E47 is number 47
    number: integer('number').notNull(),
    // 1 is first on the floor
    position: integer('position').notNull(),
    ageGroup: text('age_group', { enum: oneOf(AgeGroup) }).notNull(),
    class: text('class', { enum: oneOf(Class) }).notNull(),
    discipline: text('discipline', { enum: oneOf(Discipline) }).notNull(),
    dances: text('dances', { mode: 'json' }).$type<Dance[]>().notNull(),
    isSolo: integer('is_solo', { mode: 'boolean' }).notNull(),
  },
  (t) => [uniqueIndex('events_number_per_competition').on(t.competitionId, t.number)],
)

export const competitors = sqliteTable(
  'competitors',
  {
    id: id(),
    // A couple has two names; a solo dancer has one
    names: text('names', { mode: 'json' }).$type<string[]>().notNull(),
    // TODO: derive from the birth date once the real registration form collects it
    ageGroup: text('age_group', { enum: oneOf(AgeGroup) }),
    birthDate: text('birth_date'),
    // Null until the secretariat assigns one; unique once assigned
    backNumber: integer('back_number'),
    clubId: text('club_id')
      .notNull()
      .references(() => clubs.id),
  },
  (t) => [uniqueIndex('competitors_back_number').on(t.backNumber), index('competitors_club').on(t.clubId)],
)

export const payments = sqliteTable('payments', {
  id: id(),
  clubId: text('club_id')
    .notNull()
    .references(() => clubs.id),
  competitionId: text('competition_id').references(() => competitions.id, { onDelete: 'cascade' }),
  // A late entry at the venue has its own payment; the club's main payment covers its portal entries
  late: integer('late', { mode: 'boolean' }).notNull().default(false),
  amountDue: real('amount_due').notNull(),
  amountPaid: real('amount_paid'),
  referenceNumber: text('reference_number'),
  // TODO: phase 6 stores receipts as private files on the cloud server; until then the screenshot is kept here as a data URL
  receipt: text('receipt'),
  status: text('status', { enum: oneOf(PaymentStatus) }).notNull(),
  rejectionReason: text('rejection_reason'),
  checkedBy: text('checked_by'),
  checkedAt: text('checked_at'),
})

export const entries = sqliteTable(
  'entries',
  {
    id: id(),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id, { onDelete: 'cascade' }),
    scratched: integer('scratched', { mode: 'boolean' }).notNull().default(false),
    paymentId: text('payment_id').references(() => payments.id),
    // Added at the venue after entries closed
    late: integer('late', { mode: 'boolean' }).notNull().default(false),
  },
  (t) => [
    uniqueIndex('entries_once_per_event').on(t.eventId, t.competitorId),
    index('entries_payment').on(t.paymentId),
  ],
)

export const adjudicators = sqliteTable(
  'adjudicators',
  {
    id: id(),
    name: text('name').notNull(),
    // A to J
    letter: text('letter').notNull(),
  },
  (t) => [uniqueIndex('adjudicators_letter').on(t.letter)],
)

export const adjudicatorPins = sqliteTable(
  'adjudicator_pins',
  {
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id, { onDelete: 'cascade' }),
    // Kept readable on purpose: the admin prints these on cards and must be able to reprint them
    pin: text('pin').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.competitionId, t.adjudicatorId] }),
    uniqueIndex('pins_unique_per_competition').on(t.competitionId, t.pin),
  ],
)

export const panels = sqliteTable('panels', {
  id: id(),
  eventId: text('event_id')
    .notNull()
    .unique()
    .references(() => events.id, { onDelete: 'cascade' }),
})

export const panelMembers = sqliteTable(
  'panel_members',
  {
    panelId: text('panel_id')
      .notNull()
      .references(() => panels.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id, { onDelete: 'cascade' }),
  },
  (t) => [primaryKey({ columns: [t.panelId, t.adjudicatorId] })],
)

export const rounds = sqliteTable(
  'rounds',
  {
    id: id(),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    type: text('type', { enum: oneOf(RoundType) }).notNull(),
    // Order within the event, 1 first
    position: integer('position').notNull(),
    // How many each adjudicator marks X; null for the final
    recallNumber: integer('recall_number'),
    status: text('status', { enum: oneOf(RoundStatus) }).notNull(),
    // When the scrutineer published it; the MC reads announcements in this order
    publishedAt: text('published_at'),
  },
  (t) => [uniqueIndex('rounds_once_per_event').on(t.eventId, t.type)],
)

export const heats = sqliteTable(
  'heats',
  {
    id: id(),
    roundId: text('round_id')
      .notNull()
      .references(() => rounds.id, { onDelete: 'cascade' }),
    number: integer('number').notNull(),
  },
  (t) => [uniqueIndex('heats_number_per_round').on(t.roundId, t.number)],
)

export const heatCompetitors = sqliteTable(
  'heat_competitors',
  {
    heatId: text('heat_id')
      .notNull()
      .references(() => heats.id, { onDelete: 'cascade' }),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
  },
  (t) => [primaryKey({ columns: [t.heatId, t.competitorId] })],
)

// One row per adjudicator per round. All of an adjudicator's marks arrive together, so this means "submitted"
export const submissions = sqliteTable(
  'submissions',
  {
    roundId: text('round_id')
      .notNull()
      .references(() => rounds.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id),
    submittedAt: text('submitted_at').notNull(),
    // Set when the scrutineer typed the marks in from a paper sheet
    enteredBy: text('entered_by'),
  },
  (t) => [primaryKey({ columns: [t.roundId, t.adjudicatorId] })],
)

export const marks = sqliteTable(
  'marks',
  {
    id: id(),
    roundId: text('round_id')
      .notNull()
      .references(() => rounds.id, { onDelete: 'cascade' }),
    adjudicatorId: text('adjudicator_id')
      .notNull()
      .references(() => adjudicators.id),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
    dance: text('dance', { enum: oneOf(Dance) }).notNull(),
    kind: text('kind', { enum: ['x', 'placing'] }).notNull(),
    // Set when kind is placing
    placing: integer('placing'),
    // Server clock, so a wrong phone clock cannot reorder anything
    submittedAt: text('submitted_at').notNull(),
  },
  // Write-once: a repeated submission after a Wi-Fi drop cannot add a second mark
  (t) => [uniqueIndex('marks_once').on(t.roundId, t.adjudicatorId, t.competitorId, t.dance)],
)

export const tieDecisions = sqliteTable('tie_decisions', {
  roundId: text('round_id')
    .primaryKey()
    .references(() => rounds.id, { onDelete: 'cascade' }),
  // Recall everyone on the tie, or only those above it
  choice: text('choice', { enum: ['more', 'fewer'] }).notNull(),
  proposedBy: text('proposed_by').notNull(),
  proposedAt: text('proposed_at').notNull(),
  confirmedBy: text('confirmed_by'),
  confirmedAt: text('confirmed_at'),
})

export const results = sqliteTable(
  'results',
  {
    id: id(),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
    // The best place of a shared range, as the MC reads it (the 13 in 13th to 18th)
    place: integer('place').notNull(),
    // The whole shared range; equal when the place is not shared
    placeFrom: integer('place_from').notNull(),
    placeTo: integer('place_to').notNull(),
    // Where the competitor went out: the final, or the round that cut them. Ranking points depend on it
    stage: text('stage', { enum: oneOf(RoundType) }).notNull(),
    approvedBy: text('approved_by').notNull(),
    approvedAt: text('approved_at').notNull(),
  },
  (t) => [uniqueIndex('results_once_per_event').on(t.eventId, t.competitorId)],
)

export const pointsTable = sqliteTable('points_table', {
  id: id(),
  // 1 to 7; null is the semi-final row
  place: integer('place'),
  label: text('label').notNull(),
  points: real('points').notNull(),
  sortOrder: integer('sort_order').notNull(),
})

export const rankingPoints = sqliteTable(
  'ranking_points',
  {
    id: id(),
    competitorId: text('competitor_id')
      .notNull()
      .references(() => competitors.id),
    ageGroup: text('age_group', { enum: oneOf(AgeGroup) }).notNull(),
    class: text('class', { enum: oneOf(Class) }).notNull(),
    discipline: text('discipline', { enum: oneOf(Discipline) }).notNull(),
    competitionId: text('competition_id')
      .notNull()
      .references(() => competitions.id, { onDelete: 'cascade' }),
    eventId: text('event_id')
      .notNull()
      .references(() => events.id, { onDelete: 'cascade' }),
    points: real('points').notNull(),
  },
  (t) => [
    uniqueIndex('ranking_points_once_per_event').on(t.eventId, t.competitorId),
    index('ranking_points_category').on(t.ageGroup, t.class, t.discipline),
  ],
)

export const staffUsers = sqliteTable('staff_users', {
  id: id(),
  name: text('name').notNull(),
  username: text('username').notNull().unique(),
  role: text('role', { enum: oneOf(Role) }).notNull(),
  passwordHash: text('password_hash').notNull(),
  disabled: integer('disabled', { mode: 'boolean' }).notNull().default(false),
})

export const auditLog = sqliteTable(
  'audit_log',
  {
    id: id(),
    actorId: text('actor_id').notNull(),
    action: text('action').notNull(),
    target: text('target').notNull(),
    // What the record looked like before and after, as JSON
    before: text('before', { mode: 'json' }),
    after: text('after', { mode: 'json' }),
    at: text('at').notNull(),
  },
  (t) => [index('audit_log_at').on(t.at)],
)

// Items waiting to upload to the cloud; phase 5 reads and empties this
export const outbox = sqliteTable(
  'outbox',
  {
    id: id(),
    entity: text('entity').notNull(),
    entityId: text('entity_id').notNull(),
    operation: text('operation', { enum: ['upsert', 'delete'] }).notNull(),
    payload: text('payload', { mode: 'json' }).notNull(),
    createdAt: text('created_at').notNull(),
    sentAt: text('sent_at'),
    attempts: integer('attempts').notNull().default(0),
  },
  (t) => [index('outbox_unsent').on(t.sentAt)],
)

// Small server settings kept in the database, so a restored backup carries them: the key that signs sign-in cookies
export const settings = sqliteTable('settings', {
  key: text('key').primaryKey(),
  value: text('value').notNull(),
})
